import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
test('triagem121 preserva campos operacionais',()=>{for(const [id,titulo,expected,link] of [["oYoalVz8s4bR2iumSyhW","Carregador Fonte Apple Ipad Iphone Turbo Original Usb-c 20w","Carregador USB-C de 20 W anunciado como Apple","https://www.mercadolivre.com.br/up/MLBU4284032987?pdp_filters=item_id%3AMLB4883864997"],["P5uw3Q0IjbFoD0of4CSu","Karaoke Box Azul + Sistema Com Pontuação","Karaoke Box azul — sistema de pontuação anunciado","https://www.mercadolivre.com.br/p/MLB60860545?wid=MLB4484863171"],["p9csD1mVQKKLvmFbV1VX","Mini Ventilador Soprador Ar Turbo 130000RPM Sem Fio Recarregável USB 3 Níveis Jato Forte Portátil Multiuso Limpeza Teclado Carro Acende Churrasqueira Simake","Mini soprador Simake sem fio — três níveis anunciados","https://www.mercadolivre.com.br/p/MLB67463325?pdp_filters=item_id%3AMLB6549158890"]]){const p={id,titulo,link,preco:'preservar',linkAfiliado:'https://meli.la/preservar'},x=correctProductData(p);assert.ok(x.comentario.length>=180);for(const k of ['id','preco','linkAfiliado','link'])assert.equal(x[k],p[k]);assert.equal(x.titulo,expected);assert.deepEqual(correctProductData(x),x);assert.equal(correctProductData({...p,link:'https://produto.mercadolivre.com.br/MLB-123'}).titulo,titulo);}});
